<template>
  <li>
    <div class="tree-row" :class="{ selected: isActiveTopology }" @click="onSelect">
      <!-- 펼침 토글 -->
      <span class="toggle" v-if="hasChildren" @click.stop="open = !open">
        {{ open ? "▾" : "▸" }}
      </span>

      <!-- main에서만 체크박스 -->
      <input v-if="mode === 'main' && node.type === 'topology'" type="checkbox" :checked="isChecked"
        @change.stop="onToggle" />

      <!-- 라벨 -->
      <span class="node-label" :class="node.type" @contextmenu.prevent="onContextMenu">
        {{ node.name }}
      </span>
    </div>

    <!-- children -->
    <transition name="tree-expand">
      <ul v-if="hasChildren" v-show="open" class="children">
        <TreeNode v-for="child in node.children" :key="child.id" :node="child" :mode="mode"
          :selectedTopologies="selectedTopologies" :activeTopologyId="activeTopologyId" :topologyIndex="topologyIndex"
          :depth="depth + 1" @select-node="$emit('select-node', $event)"
          @toggle-topology="$emit('toggle-topology', $event)" @open-context-menu="$emit('open-context-menu', $event)" />
      </ul>
    </transition>
  </li>
</template>


<script setup>
import { ref, computed, defineProps, defineEmits, watch } from "vue"

const props = defineProps({
  node: Object,
  mode: String,

  // main 전용
  selectedTopologies: Object,

  // modal 전용
  activeTopologyId: [String, Number],
  topologyIndex: Number,

  depth: Number
})

const emit = defineEmits([
  "select-node",
  "toggle-topology",
  "open-context-menu"
])

/* children 여부 */
const hasChildren = computed(
  () => Array.isArray(props.node.children) && props.node.children.length > 0
)

/* 펼침 상태 */
const open = ref(false)

/* 🔑 main일 때는 기본적으로 전부 open */
/* Editor(modal) 열릴 때 초기 open 규칙 */
watch(
  () => [props.mode, props.activeTopologyId],
  ([mode, id]) => {

    /* ✅ 1️⃣ main: 항상 전부 open */
    if (mode === "main") {
      open.value = true
      return
    }

    /* ✅ 2️⃣ modal: 선택된 topology 기준 제어 */
    if (mode === "modal") {

      // 2-1) 선택된 topology 루트
      if (props.node.type === "topology" && props.node.id === id) {
        open.value = true
        return
      }

      // 2-2) 그 바로 아래 1단계
      if (
        props.depth === 1 &&
        props.node.parentId === id
      ) {
        open.value = true
        return
      }

      // 2-3) 나머지는 닫기
      open.value = false
    }
  },
  { immediate: true }
)

/* main 전용: 체크 여부 */
const isChecked = computed(() => {
  if (props.mode !== "main") return false
  if (props.node.type !== "topology") return false
  if (props.topologyIndex === undefined) return false
  return props.selectedTopologies?.has(props.node.id)
})

/* modal 전용: 선택 강조 */
const isActiveTopology = computed(() => {
  if (props.mode !== "modal") return false
  if (props.node.type !== "topology") return false
  return props.node.id === props.activeTopologyId
})

/* 공통: 선택 */
const onSelect = () => {
  emit("select-node", props.node)
}

/* main 전용: 체크 토글 */
const onToggle = e => {
  const payload = {
    topologyIndex: props.node.__topologyIndex,
    checked: e.target.checked
  }

  console.log("🔥 TreeNode emit payload", payload)

  emit("toggle-topology", payload)


}

/* 우클릭 */
const onContextMenu = (e) => {
  emit("open-context-menu", {
    event: e,
    node: props.node
  })
}
</script>

<style scoped>
.tree-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0;
}

.toggle {
  font-size: 18px;
  /* 또는 20px */
  font-weight: bold;
  cursor: pointer;
  user-select: none;
  line-height: 1;
}

.children {
  padding-left: 20px;
  /* 기존보다 조금 더 */
  border-left: 1px dashed #d1d5db;
  /* 구조가 보이게 */
  margin-left: 5px;
}

.node-label {
  cursor: default;
}

.node-label.element {
  font-weight: 600;
}

.node-label.property-group {
  font-weight: 600;
  color: #1f2937;
}

.node-label.property {
  font-size: 13px;
  color: #374151;
}

.tree-row.selected {
  background: #eef2ff;
  border-radius: 4px;
}

.tree-row.selected .node-label {
  font-weight: 600;
  color: #1e3a8a;
}

/* ===============================
   Tree expand / collapse animation
   =============================== */

.tree-expand-enter-active,
.tree-expand-leave-active {
  transition:
    max-height 0.25s ease,
    opacity 0.2s ease;
  overflow: hidden;
}

.tree-expand-enter-from,
.tree-expand-leave-to {
  max-height: 0;
  opacity: 0;
}

.tree-expand-enter-to,
.tree-expand-leave-from {
  max-height: 600px; /* 충분히 큰 값 */
  opacity: 1;
}
</style>