  </div>


  <NodeContextMenu :visible="contextMenu.visible" :x="contextMenu.x" :y="contextMenu.y" :item="contextMenu.item"
    @edit="openPropertyModal" @delete="deleteNode" @close="closeContextMenu" />

  <NodePropertyModal :visible="showNodeModal"  :initialTopologyId="contextMenu.topologyId" :treeItems="treeItems"
    @close="showNodeModal = false" />

</template>


<script setup>
import { ref, watch, computed, nextTick, onMounted, reactive, onUnmounted } from "vue";
import { useDropZoneStore } from "../store/dropZoneStore.js";
