const startItem = ref(null);
const maxTopology = ref(0);

const progressStore = useProgressStore();
const router = useRouter();
const demandArea = ref("");

var dialogText = ref("");
const showDialog = ref(false);

const uploadMode = ref("manual");

const isLoading = ref(false);

const selectedCaseId = ref(null);

const svgPaths = ref([])
const svgWidth = ref(0)
const svgHeight = ref(0)

const selectedTopologies = ref(new Set())

const icon_label = {
  원전: "Nuclear_power.png",
  석탄화력: "coal_fired_power.png",
  가스복합: "gas_combined_power.png",
  소수력: "small_hydropower.png",
  '765kV': "electricity-tower_2628822.png",
  '345kV': "electricity-tower_2628822.png",
  '154kV': "electricity-tower_2628822.png",
  '22.9kV': "electricity-tower_2628822.png",
  태양광: "solar-energy_2729361.png",
  풍력: "turbine_7294935.png",
  해상풍력: "eolian_12470907.png",
  ESS: "battery_17949309.png",
  EV: "electric-car_3444059.png",
  EVC: "vehicle_15533381.png",
  DR: "motivation_17146362.png",
  VPP: "transformation_8044393.png",
