const case_definitions = [
  {
    id: "CASE_A",
    name: "A Grid Interconnection Standard",
    description: "분산형 재생에너지를 전력 계통에 안전하게 접속하기 위한 계통 영향이 계측 가능한 최소 실증 요건인 계통 접속 기준 시나리오입니다.",
    details: [
      "KEPCO 배전망 접속 기준을 충족하기 위한 전압·주파수 안정성 실증형 구성",
      "인버터 제어 응답성 측정 및 계통 연계 알고리즘 검증",
      "전압 유지 - 접속점에서 ±5% 이내 유지 검증",
      "주파수 허용 범위 - 59.8~60.2Hz 범위 내 제어 검증",
      "PV - 주간 기저 발전량 확보",
      "Wind - 야간 출력 보완",
      "ESS - 출력 조정 및 보호 릴레이 중심 설계"
    ],
    filePath: "../TopologyList/case1_계통접속기준형.txt"
  },
  {
    id: "CASE_B",
    name: "B Reserve Power Requirement",
    description: "재생에너지의 출력 변동성을 보완하여 실시간 수요-공급 균형을 유지하는 예비력 확보 기능 시나리오입니다.",
    details: [
      "ESS 충방전 효율 및 예비력 보유율을 검증하기 위한 예비력 배분 자동화 로직 실증형 구성",
      "운전 예비력 - ESS 충방전 제어 검증을 통한 순간적 예비력 확보 ",
